const products: Product[] = [
  { id: '1', title: 'سلة مؤونة سورية', category: 'food', governorate: 'دمشق', price: 18, store: 'مونة الشام', featured: true },
  { id: '2', title: 'زيت زيتون بلدي 5 ليتر', category: 'food', governorate: 'إدلب', price: 32, store: 'خير الشمال' },
  { id: '3', title: 'طقم ملابس أطفال قطني', category: 'fashion', governorate: 'حلب', price: 22, store: 'دار الياسمين', featured: true },
  { id: '4', title: 'دراجة كهربائية للمدينة', category: 'electronics', governorate: 'حمص', price: 285, store: 'تقنية سوريا' },
  { id: '5', title: 'مولدة ديزل 60 KVA', category: 'machines', governorate: 'حلب', price: 6400, store: 'حلول الطاقة', large: true },
  { id: '6', title: 'رافعة شوكية 2.5 طن', category: 'machines', governorate: 'دمشق', price: 11800, store: 'المهندس للآليات', large: true },
];
const categoryKeys = ['all', 'food', 'fashion', 'electronics'];
const categoryLabels: Record<string, string> = { all: 'all', food: 'food', fashion: 'fashion', electronics: 'electronics', machines: 'machines' };
const extras: Record<Language, Record<string, string>> = {
  ar: { support: 'الدعم', supportTitle: 'مركز الدعم المباشر', supportText: 'اسأل فريق المتجر عن الطلب أو الشحن أو الاستلام.', dataSaver: 'توفير البيانات', dataSaverOn: 'مفعّل', ai: 'مساعد القط الطائر', visualSearch: 'البحث بالصور', tryOn: 'استوديو تجربة الألوان', reels: 'فيديوهات التسوق', groupBuy: 'الشراء الجماعي', cod: 'الدفع عند الباب', manualPay: 'الدفع اليدوي بين البائع والمشتري', settlement: 'تسوية يدوية بين البائع والإدارة', choosePayment: 'اختر طريقة الدفع', paymentNote: 'لا يتم الدفع الإلكتروني في هذه النسخة التجريبية.', sendMessage: 'إرسال رسالة', messagePlaceholder: 'اكتب رسالتك هنا…', offlineReady: 'السلة محفوظة ويمكن مزامنتها عند عودة الشبكة', featureDemo: 'واجهة تجريبية جاهزة للربط', location: 'موقع التسليم', landmark: 'أقرب نقطة دالة', mapPin: 'تحديد نقطة على الخريطة', pinAdded: 'تم تحديد النقطة', deliveryMode: 'طريقة الاستلام', doorDelivery: 'التوصيل إلى الباب', pickupPoint: 'نقطة استلام شريكة' },
  tr: { support: 'Destek', supportTitle: 'Canlı destek merkezi', supportText: 'Sipariş, kargo veya teslim alma hakkında bize sorun.', dataSaver: 'Veri tasarrufu', dataSaverOn: 'Açık', ai: 'Uçan kedi asistanı', visualSearch: 'Görsel arama', tryOn: 'Renk deneme stüdyosu', reels: 'Alışveriş videoları', groupBuy: 'Toplu satın alma', cod: 'Kapıda ödeme', manualPay: 'Alıcı ve satıcı arasında manuel ödeme', settlement: 'Satıcı ve yönetim arasında manuel mutabakat', choosePayment: 'Ödeme yöntemi seçin', paymentNote: 'Bu demoda elektronik ödeme yapılmaz.', sendMessage: 'Mesaj gönder', messagePlaceholder: 'Mesajınızı yazın…', offlineReady: 'Sepet kaydedildi; bağlantı gelince senkronize edilir', featureDemo: 'Entegrasyona hazır demo arayüz', location: 'Teslimat konumu', landmark: 'En yakın bilinen nokta', mapPin: 'Haritada nokta seç', pinAdded: 'Nokta seçildi', deliveryMode: 'Teslim alma yöntemi', doorDelivery: 'Kapıya teslimat', pickupPoint: 'Ortak teslim noktası' },
  en: { support: 'Support', supportTitle: 'Live support center', supportText: 'Ask us about an order, shipping, or pickup.', dataSaver: 'Data saver', dataSaverOn: 'On', ai: 'Flying cat assistant', visualSearch: 'Visual search', tryOn: 'Color try-on studio', reels: 'Shoppable videos', groupBuy: 'Group buying', cod: 'Cash on delivery', manualPay: 'Manual payment between buyer and seller', settlement: 'Manual settlement between seller and admin', choosePayment: 'Choose a payment method', paymentNote: 'Electronic payments are not active in this demo.', sendMessage: 'Send message', messagePlaceholder: 'Write your message…', offlineReady: 'Cart saved and ready to sync when online', featureDemo: 'Demo interface ready for integration', location: 'Delivery location', landmark: 'Nearest landmark', mapPin: 'Choose a map pin', pinAdded: 'Pin selected', deliveryMode: 'Delivery method', doorDelivery: 'Door delivery', pickupPoint: 'Partner pickup point' },
  zh: { support: '支持', supportTitle: '在线支持中心', supportText: '咨询订单、配送或取货问题。', dataSaver: '节省流量', dataSaverOn: '已开启', ai: '飞猫助手', visualSearch: '图片搜索', tryOn: '颜色试用工作室', reels: '购物短视频', groupBuy: '团购', cod: '货到付款', manualPay: '买家与卖家之间的手动付款', settlement: '卖家与管理员之间的手动结算', choosePayment: '选择付款方式', paymentNote: '演示版未启用电子支付。', sendMessage: '发送消息', messagePlaceholder: '输入消息…', offlineReady: '购物车已保存，联网后同步', featureDemo: '可连接服务的演示界面', location: '配送位置', landmark: '最近的地标', mapPin: '选择地图位置', pinAdded: '已选择位置', deliveryMode: '取货方式', doorDelivery: '送货上门', pickupPoint: '合作取货点' },
  ja: { support: 'サポート', supportTitle: 'ライブサポート', supportText: '注文、配送、受け取りについてお問い合わせください。', dataSaver: 'データセーバー', dataSaverOn: 'オン', ai: '空飛ぶ猫アシスタント', visualSearch: '画像検索', tryOn: 'カラー試着スタジオ', reels: 'ショッピング動画', groupBuy: '共同購入', cod: '代引き', manualPay: '購入者と販売者の手動決済', settlement: '販売者と管理者の手動精算', choosePayment: '支払い方法を選択', paymentNote: 'デモ版では電子決済は無効です。', sendMessage: 'メッセージを送信', messagePlaceholder: 'メッセージを入力…', offlineReady: 'カートを保存しました。接続時に同期します', featureDemo: '連携用デモ画面', location: '配送場所', landmark: '最寄りの目印', mapPin: '地図で位置を選択', pinAdded: '位置を選択しました', deliveryMode: '受け取り方法', doorDelivery: '玄関先配送', pickupPoint: '提携受け取り所' },
};

export default function App() {
  const [language, setLanguage] = useState<Language>('ar'); const t = { ...translations[language], ...extras[language] }; const rtl = isRTL(language);
  const [page, setPage] = useState('home'); const [category, setCategory] = useState('all'); const [query, setQuery] = useState(''); const [dataSaver, setDataSaver] = useState(true); const [aiOpen, setAiOpen] = useState(false); const [menuOpen, setMenuOpen] = useState(false); const [accountView, setAccountView] = useState<'main' | 'settings' | 'following'>('main'); const [followedStores, setFollowedStores] = useState<string[]>(['مونة الشام', 'خير الشمال']);
  const [accountRole, setAccountRole] = useState<AccountRole>('CUSTOMER');
  const [cart, setCart] = useState<CartLine[]>([]); const [selected, setSelected] = useState<Product | null>(null); const [room, setRoom] = useState<'small' | 'large' | 'admin' | 'merchant' | null>(null); const [feature, setFeature] = useState<'visual' | 'tryon' | 'reels' | 'group' | null>(null);
  const [notice, setNotice] = useState(''); const [languageOpen, setLanguageOpen] = useState(false); const [ordered, setOrdered] = useState(false);
  useEffect(() => { AsyncStorage.getItem('almatjar-demo-cart').then(value => { if (value) setCart(JSON.parse(value)); }).catch(() => undefined); AsyncStorage.getItem('almatjar-demo-data-saver').then(value => { if (value) setDataSaver(value === 'true'); }).catch(() => undefined); }, []);
  useEffect(() => { AsyncStorage.setItem('almatjar-demo-cart', JSON.stringify(cart)).catch(() => undefined); }, [cart]);
  useEffect(() => { AsyncStorage.setItem('almatjar-demo-data-saver', String(dataSaver)).catch(() => undefined); }, [dataSaver]);
  const visible = useMemo(() => products.filter(p => (category === 'all' || p.category === category) && `${p.title} ${p.store} ${p.governorate}`.toLowerCase().includes(query.trim().toLowerCase())), [category, query]);
  const total = cart.reduce((sum, item) => sum + item.price * item.quantity, 0); const shipping = cart.length ? 4 : 0;
  const notify = (message: string) => { setNotice(message); setTimeout(() => setNotice(''), 2300); };
  const add = (product: Product) => { setCart(current => current.some(x => x.id === product.id) ? current.map(x => x.id === product.id ? { ...x, quantity: x.quantity + 1 } : x) : [...current, { ...product, quantity: 1 }]); notify(t.added); };
  const chooseLanguage = (next: Language) => { setLanguage(next); setLanguageOpen(false); };
  return <SafeAreaView style={styles.safe}><StatusBar barStyle="light-content" backgroundColor={CREAM} /><View style={styles.app}>
    <Header t={t} rtl={rtl} cartCount={cart.length} onCart={() => setPage('cart')} onAccount={() => { setAccountView('main'); setPage('account'); }} onLanguage={() => setLanguageOpen(true)} onMenu={() => setMenuOpen(true)} />
    {page === 'home' && <Home t={t} rtl={rtl} language={language} query={query} setQuery={setQuery} category={category} setCategory={setCategory} visible={visible} onProduct={setSelected} onAdd={add} onRoom={setRoom} onFeature={setFeature} />}
    {page === 'stores' && <Stores t={t} rtl={rtl} />}
    {page === 'cart' && <Cart t={t} rtl={rtl} cart={cart} total={total} shipping={shipping} onRemove={(id: string) => setCart(c => c.filter(x => x.id !== id))} onCheckout={() => setOrdered(true)} />}
    {page === 'account' && <Account t={t} rtl={rtl} role={accountRole} view={accountView} setView={setAccountView} onRoom={setRoom} onAdmin={() => accountRole === 'ADMIN' && setPage('admin')} onMerchant={() => { setAccountRole('MERCHANT'); setPage('merchant'); }} dataSaver={dataSaver} setDataSaver={setDataSaver} followedStores={followedStores} setFollowedStores={setFollowedStores} />}
    {page === 'support' && <Support t={t} rtl={rtl} onFeature={setFeature} />}
    {page === 'reels' && <Reels t={t} rtl={rtl} onFeature={setFeature} />}
    {page === 'merchant' && <MerchantDashboard t={t} rtl={rtl} onNotify={notify} onBack={() => setPage('account')} />} {page === 'admin' && <AdminPage t={t} rtl={rtl} onRoom={setRoom} />}
    <Pressable onPress={() => setAiOpen(!aiOpen)} style={styles.aiFab}><Text style={styles.aiFabText}>✦</Text></Pressable>
    {aiOpen && <View style={styles.aiBubble}><Text style={styles.aiBubbleTitle}>المساعد الذكي</Text><Text style={styles.aiBubbleText}>مساعد بصري تجريبي ناعم للتوصيات ونقاط الاستلام. ربط نموذج AI الحقيقي يتم عبر الخادم.</Text><Text style={styles.aiBubbleText}>PUDO · {t.groupBuy} · {t.visualSearch}</Text></View>}
    <BottomNav t={t} rtl={rtl} page={page} setPage={setPage} cartCount={cart.length} />
  </View>
  <Modal visible={languageOpen} transparent animationType="fade" onRequestClose={() => setLanguageOpen(false)}><View style={styles.overlay}><View style={styles.languageBox}><Text style={styles.modalTitle}>{t.sections} / Language</Text>{languages.map(item => <Pressable key={item.key} onPress={() => chooseLanguage(item.key)} style={[styles.languageRow, item.key === language && styles.languageSelected]}><Text style={styles.languageNative}>{item.native}</Text><Text style={styles.languageLabel}>{item.label}</Text>{item.key === language && <Text style={styles.check}>✓</Text>}</Pressable>)}<Button label={t.backShopping} onPress={() => setLanguageOpen(false)} /></View></View></Modal>
  <Modal visible={menuOpen} transparent animationType="slide" onRequestClose={() => setMenuOpen(false)}><View style={styles.overlay}><View style={styles.menuSheet}><Text style={styles.modalTitle}>☰ {t.stores}</Text><Text style={styles.menuSubtitle}>{t.sections}</Text><Text style={styles.menuGroupTitle}>{t.smallStore}</Text><View style={styles.menuGrid}>{['غذائيات','ألبسة','ساعات','نظارات','قرطاسية','جميع الأقسام'].map(item => <Pressable key={item} style={styles.menuChip} onPress={() => { setCategory(item === 'جميع الأقسام' ? 'all' : category); setMenuOpen(false); setPage('home'); }}><Text style={styles.menuChipText}>{item}</Text></Pressable>)}</View><Text style={styles.menuGroupTitle}>{t.largeStore}</Text><View style={styles.menuGrid}>{['سيارات','قطع غيار','ماكينات','خزانات','حاويات','معدات ثقيلة','طلبات عرض'].map(item => <Pressable key={item} style={styles.menuChip} onPress={() => { setMenuOpen(false); setPage('stores'); }}><Text style={styles.menuChipText}>{item}</Text></Pressable>)}</View><Button label={t.backShopping} onPress={() => setMenuOpen(false)} /></View></View></Modal>
  <Modal visible={!!selected} transparent animationType="slide" onRequestClose={() => setSelected(null)}>{selected && <ProductModal t={t} rtl={rtl} product={selected} onClose={() => setSelected(null)} onAdd={() => { add(selected); setSelected(null); }} />}</Modal>
  <Modal visible={!!room} transparent animationType="slide" onRequestClose={() => setRoom(null)}>{room && <RoomModal t={t} rtl={rtl} room={room} onClose={() => setRoom(null)} onNotify={notify} />}</Modal>
  <Modal visible={!!feature} transparent animationType="slide" onRequestClose={() => setFeature(null)}>{feature && <FeatureModal t={t} rtl={rtl} feature={feature} onClose={() => setFeature(null)} onNotify={notify} />}</Modal>
  <Modal visible={ordered} transparent animationType="fade" onRequestClose={() => setOrdered(false)}><View style={styles.overlay}><View style={styles.successBox}><Text style={styles.successIcon}>✓</Text><Text style={styles.modalTitle}>{t.orderPlaced}</Text><Text style={styles.modalText}>{t.demoNote}</Text><Button label={t.backShopping} onPress={() => { setOrdered(false); setCart([]); setPage('home'); }} /></View></View></Modal>
  {!!notice && <View style={styles.toast}><Text style={styles.toastText}>{notice}</Text></View>}
  </SafeAreaView>;
}

function Header({ t, rtl, cartCount, onCart, onAccount, onLanguage, onMenu }: any) { return <View style={[styles.header, rtl && styles.rowRTL]}><Pressable onPress={onMenu} style={styles.headerMenuButton}><Text style={styles.headerMenuText}>☰</Text></Pressable><View style={styles.brandBlock}><Text style={styles.brand}>{t.brand}</Text><Text style={styles.brandSub}>{t.country}</Text></View><View style={styles.headerActions}><Pressable onPress={onLanguage} style={styles.langButton}><Text style={styles.langButtonText}>文 A ع</Text></Pressable><Pressable onPress={onAccount} style={styles.circle}><Text style={styles.circleText}>◉</Text></Pressable><Pressable onPress={onCart} style={styles.cartCircle}><Text style={styles.circleText}>🛒</Text>{cartCount > 0 && <View style={styles.badge}><Text style={styles.badgeText}>{cartCount}</Text></View>}</Pressable></View></View>; }
function Home({ t, rtl, language, query, setQuery, category, setCategory, visible, onProduct, onAdd, onRoom, onFeature }: any) { return <ScrollView contentContainerStyle={styles.content} showsVerticalScrollIndicator={false}>
  <View style={[styles.search, rtl && styles.rowRTL]}><Text style={styles.searchIcon}>⌕</Text><TextInput value={query} onChangeText={setQuery} placeholder={t.search} placeholderTextColor={MUTED} style={[styles.searchInput, rtl && styles.textRTL]} /><Pressable onPress={() => onFeature('visual')} style={styles.visualSearchButton}><Text style={styles.visualSearchIcon}>⌾</Text></Pressable></View>
  <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.stories}>{['👩🏻‍🍳','🧕🏻','👨🏻‍🔧','👩🏻‍💼','🧔🏻'].map((icon, index) => <Pressable key={index} style={styles.story} onPress={() => onProduct(visible[index % Math.max(visible.length, 1)] || products[0])}><View style={[styles.storyRing, index % 2 ? styles.storyRingGold : styles.storyRingBurgundy]}><Text style={styles.storyIcon}>{icon}</Text><Text style={styles.storyPlay}>▶</Text></View><Text style={styles.storyLabel}>{[t.reels, t.ai, t.stores, 'عروض اليوم', 'الأكثر مشاهدة'][index]}</Text></Pressable>)}</ScrollView>
  <View style={[styles.flashBanner, rtl && styles.rowRTL]}><View style={{ flex: 1 }}><Text style={styles.flashTitle}>⚡ {t.reels}</Text><Text style={styles.flashText}>{t.clearCosts}</Text></View><View style={styles.flashTimer}><Text style={styles.flashTimerText}>01:20</Text><Text style={styles.flashTimerCaption}>FLASH</Text></View></View>
  <SectionTitle title={t.sections} action={t.all} rtl={rtl} /><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chips}>{categoryKeys.map(key => <Pressable key={key} onPress={() => setCategory(key)} style={[styles.chip, category === key && styles.chipActive]}><Text style={[styles.chipText, category === key && styles.chipTextActive]}>{categoryName(t, key, language)}</Text></Pressable>)}</ScrollView>
  <SectionTitle title={t.featured} action="" rtl={rtl} /><View style={styles.productGrid}>{visible.map((item: Product) => <ProductCard key={item.id} t={t} product={item} onPress={() => onProduct(item)} onAdd={() => onAdd(item)} />)}</View>
  <View style={[styles.publicNote, rtl && styles.rowRTL]}><Text style={styles.publicNoteIcon}>✓</Text><Text style={[styles.publicNoteText, rtl && styles.textRTL]}>مساحات التاجر والإدارة متاحة من الحسابات المصرّح بها فقط.</Text></View>
 </ScrollView>; }
function categoryName(t: any, key: string, language: Language) { const names: Record<Language, Record<string, string>> = { ar: { food: 'غذائيات', fashion: 'ملابس', electronics: 'إلكترونيات' }, tr: { food: 'Gıda', fashion: 'Moda', electronics: 'Elektronik' }, en: { food: 'Food', fashion: 'Fashion', electronics: 'Electronics' }, zh: { food: '食品', fashion: '服装', electronics: '电子产品' }, ja: { food: '食品', fashion: '衣類', electronics: '電子機器' } }; return key === 'all' ? t.all : key === 'machines' ? t.largeStore : names[language][key] || key; }
function SectionTitle({ title, action, rtl }: any) { return <View style={[styles.sectionTitle, rtl && styles.rowRTL]}><Text style={styles.sectionHeading}>{title}</Text>{action ? <Text style={styles.sectionAction}>{action}</Text> : null}</View>; }
function ProductCard({ t, product, onPress, onAdd }: any) { return <Pressable onPress={onPress} style={({ pressed }) => [styles.productCard, pressed && { opacity: .82 }]}><View style={[styles.productImage, product.large ? styles.machineImage : styles.groceryImage]}><Text style={styles.productEmoji}>{product.large ? '⚙' : product.category === 'fashion' ? '✦' : product.category === 'electronics' ? '⌁' : '✿'}</Text>{product.featured && <View style={styles.featured}><Text style={styles.featuredText}>{t.promotion}</Text></View>}</View><Text style={styles.productTitle} numberOfLines={2}>{product.title}</Text><Text style={styles.productStore}>{product.store} · {product.governorate}</Text><View style={styles.productBottom}><Text style={styles.price}>{product.price} <Text style={styles.priceUnit}>USD</Text></Text><Pressable onPress={onAdd} style={styles.addButton}><Text style={styles.addButtonText}>+</Text></Pressable></View></Pressable>; }
function StoryBubble({ icon, label }: { icon: string; label: string }) { return <View style={styles.story}><View style={styles.storyRing}><Text style={styles.storyIcon}>{icon}</Text><Text style={styles.storyPlay}>▶</Text></View><Text style={styles.storyLabel}>{label}</Text></View>; }
function Stores({ t, rtl }: any) { return <ScrollView contentContainerStyle={styles.content}><Text style={[styles.pageTitle, rtl && styles.textRTL]}>{t.stores}</Text><Text style={[styles.pageLead, rtl && styles.textRTL]}>{t.demoNote}</Text><View style={styles.publicNote}><Text style={styles.publicNoteIcon}>⌂</Text><Text style={[styles.publicNoteText, rtl && styles.textRTL]}>تصفح المتاجر والمنتجات من هنا. إدارة المتجر والتحليلات لا تظهر إلا داخل حساب التاجر بعد اعتماده.</Text></View></ScrollView>; }
function RoomLink({ t, icon, title, text, onPress }: any) { return <Pressable style={styles.roomCard} onPress={onPress}><View style={styles.roomIcon}><Text>{icon}</Text></View><View style={styles.roomCopy}><Text style={styles.roomTitle}>{title}</Text><Text style={styles.roomText}>{text}</Text></View><Text style={styles.arrow}>→</Text></Pressable>; }
function Cart({ t, rtl, cart, total, shipping, onRemove, onCheckout }: any) { const [method, setMethod] = useState<'cod' | 'manual'>('cod'); const [delivery, setDelivery] = useState<'door' | 'pickup'>('door'); const [landmark, setLandmark] = useState(''); const [pinSet, setPinSet] = useState(false); return <ScrollView contentContainerStyle={styles.content}><Text style={[styles.pageTitle, rtl && styles.textRTL]}>{t.cart}</Text>{!cart.length ? <View style={styles.empty}><Text style={styles.emptyIcon}>🛒</Text><Text style={styles.emptyTitle}>{t.emptyCart}</Text><Text style={styles.pageLead}>{t.browse}</Text></View> : <><Text style={styles.pageLead}>{cart.length} {t.product}</Text>{cart.map((line: CartLine) => <View key={line.id} style={[styles.cartLine, rtl && styles.rowRTL]}><View style={styles.cartThumb}><Text style={styles.productEmoji}>{line.large ? '⚙' : '✿'}</Text></View><View style={{ flex: 1 }}><Text style={styles.roomTitle}>{line.title}</Text><Text style={styles.productStore}>{line.quantity} × {line.price} USD</Text></View><Pressable onPress={() => onRemove(line.id)}><Text style={styles.remove}>×</Text></Pressable></View>)}<View style={styles.invoice}><Text style={styles.invoiceTitle}>{t.transparent}</Text><Row label={t.productsPrice} value={`${total} USD`} /><Row label={t.shipping} value={`${shipping} USD`} /><Row label={t.customs} value={t.customsPending} /><View style={styles.invoiceDivider} /><Row label={t.totalBeforeCustoms} value={`${total + shipping} USD`} strong /></View><Text style={styles.paymentHeading}>{t.location}</Text><TextInput value={landmark} onChangeText={setLandmark} placeholder={t.landmark} placeholderTextColor={MUTED} style={styles.supportInput} /><Button label={pinSet ? t.pinAdded : t.mapPin} secondary onPress={() => setPinSet(true)} /><Text style={styles.paymentHeading}>{t.deliveryMode}</Text><Pressable onPress={() => setDelivery('door')} style={[styles.paymentOption, delivery === 'door' && styles.paymentSelected]}><Text style={styles.paymentIcon}>🚚</Text><Text style={styles.roomTitle}>{t.doorDelivery}</Text></Pressable><Pressable onPress={() => setDelivery('pickup')} style={[styles.paymentOption, delivery === 'pickup' && styles.paymentSelected]}><Text style={styles.paymentIcon}>📦</Text><Text style={styles.roomTitle}>{t.pickupPoint}</Text></Pressable><Text style={styles.paymentHeading}>{t.choosePayment}</Text><Pressable onPress={() => setMethod('cod')} style={[styles.paymentOption, method === 'cod' && styles.paymentSelected]}><Text style={styles.paymentIcon}>🚪</Text><View style={{ flex: 1 }}><Text style={styles.roomTitle}>{t.cod}</Text><Text style={styles.productStore}>{t.paymentNote}</Text></View>{method === 'cod' && <Text style={styles.check}>✓</Text>}</Pressable><Pressable onPress={() => setMethod('manual')} style={[styles.paymentOption, method === 'manual' && styles.paymentSelected]}><Text style={styles.paymentIcon}>🤝</Text><View style={{ flex: 1 }}><Text style={styles.roomTitle}>{t.manualPay}</Text><Text style={styles.productStore}>{t.settlement}</Text></View>{method === 'manual' && <Text style={styles.check}>✓</Text>}</Pressable><Button label={t.checkout} onPress={onCheckout} /></>}</ScrollView>; }
function Row({ label, value, strong }: any) { return <View style={styles.invoiceRow}><Text style={[styles.invoiceLabel, strong && styles.strong]}>{label}</Text><Text style={[styles.invoiceValue, strong && styles.strong]}>{value}</Text></View>; }
function Account({ t, rtl, role, view, setView, onRoom, onAdmin, onMerchant, dataSaver, setDataSaver, followedStores, setFollowedStores }: any) { const title = view === 'settings' ? 'إعدادات الحساب' : view === 'following' ? 'المتاجر التي تتابعها' : t.account; if (view === 'settings') return <ScrollView contentContainerStyle={styles.content}><Pressable onPress={() => setView('main')} style={styles.backLink}><Text style={styles.backLinkText}>‹ {t.backShopping}</Text></Pressable><Text style={[styles.pageTitle, rtl && styles.textRTL]}>{title}</Text><SettingItem icon='◉' label='اللغة والتفضيلات' value='العربية · RTL' /><SettingItem icon='⌁' label='الإشعارات' value='إشعارات الطلبات والعروض مفعّلة' /><View style={styles.settingRow}><View style={{ flex: 1 }}><Text style={styles.roomTitle}>{t.dataSaver}</Text><Text style={styles.productStore}>{t.offlineReady}</Text></View><Pressable onPress={() => setDataSaver(!dataSaver)} style={[styles.switch, dataSaver && styles.switchOn]}><View style={[styles.switchKnob, dataSaver && styles.switchKnobOn]} /></Pressable></View><SettingItem icon='⌖' label='عنوان التوصيل' value='أقرب نقطة دالة · قابل للتعديل' /><SettingItem icon='▣' label='طريقة الدفع' value={t.cod} /><Text style={[styles.disclaimer, rtl && styles.textRTL]}>{t.demoNote}</Text></ScrollView>; if (view === 'following') return <ScrollView contentContainerStyle={styles.content}><Pressable onPress={() => setView('main')} style={styles.backLink}><Text style={styles.backLinkText}>‹ {t.backShopping}</Text></Pressable><Text style={[styles.pageTitle, rtl && styles.textRTL]}>{title}</Text><Text style={[styles.pageLead, rtl && styles.textRTL]}>تحديثات وعروض المتاجر التي اخترت متابعتها.</Text>{followedStores.map((store: string) => <View key={store} style={styles.followedCard}><View style={styles.storeAvatar}><Text style={styles.storeAvatarText}>{store.slice(0, 1)}</Text></View><View style={{ flex: 1 }}><Text style={styles.roomTitle}>{store}</Text><Text style={styles.productStore}>متجر موثوق · عروض جديدة أسبوعيًا</Text></View><Pressable onPress={() => setFollowedStores(followedStores.filter((item: string) => item !== store))} style={styles.followButton}><Text style={styles.followButtonText}>متابَع</Text></Pressable></View>)}<Button label='اكتشاف متاجر جديدة' onPress={() => setView('main')} /></ScrollView>; return <ScrollView contentContainerStyle={styles.content}><Text style={[styles.pageTitle, rtl && styles.textRTL]}>{t.account}</Text><View style={styles.profile}><View style={styles.avatar}><Text>م</Text></View><View><Text style={styles.roomTitle}>{role === 'MERCHANT' ? 'حساب تاجر / شركة' : role === 'ADMIN' ? 'حساب المدير' : t.buyer}</Text><Text style={styles.productStore}>{t.loginNote}</Text></View></View><View style={styles.settingRow}><View style={{ flex: 1 }}><Text style={styles.roomTitle}>{t.dataSaver}</Text><Text style={styles.productStore}>{t.offlineReady}</Text></View><Pressable onPress={() => setDataSaver(!dataSaver)} style={[styles.switch, dataSaver && styles.switchOn]}><View style={[styles.switchKnob, dataSaver && styles.switchKnobOn]} /></Pressable></View><Pressable style={styles.accountRow} onPress={() => setView('settings')}><Text style={styles.accountIcon}>⚙</Text><Text style={styles.accountText}>إعدادات الحساب</Text><Text style={styles.arrow}>→</Text></Pressable><Pressable style={styles.accountRow} onPress={() => setView('following')}><Text style={styles.accountIcon}>♡</Text><Text style={styles.accountText}>المتاجر التي تتابعها</Text><Text style={styles.arrow}>→</Text></Pressable>{[t.cart, t.stores, t.promotion].map((item: string) => <View key={item} style={[styles.accountRow, rtl && styles.rowRTL]}><Text style={styles.accountIcon}>◌</Text><Text style={styles.accountText}>{item}</Text><Text style={styles.arrow}>→</Text></View>)}{role === 'MERCHANT' ? <Pressable style={styles.accountRow} onPress={onMerchant}><Text style={styles.accountIcon}>▥</Text><Text style={styles.accountText}>غرفة التاجر والتحليلات</Text><Text style={styles.arrow}>→</Text></Pressable> : <Pressable style={styles.accountRow} onPress={onMerchant}><Text style={styles.accountIcon}>＋</Text><Text style={styles.accountText}>إنشاء حساب تاجر / شركة</Text><Text style={styles.arrow}>→</Text></Pressable>}{role === 'ADMIN' && <Pressable style={styles.adminLink} onPress={onAdmin}><Text style={styles.adminLinkText}>{t.adminReview}</Text></Pressable>}<Text style={[styles.disclaimer, rtl && styles.textRTL]}>{t.demoNote}</Text></ScrollView>; } function SettingItem({ icon, label, value }: any) { return <View style={styles.settingItem}><Text style={styles.settingItemIcon}>{icon}</Text><View style={{ flex: 1 }}><Text style={styles.roomTitle}>{label}</Text><Text style={styles.productStore}>{value}</Text></View><Text style={styles.arrow}>›</Text></View>; }
function Support({ t, rtl, onFeature }: any) { const [message, setMessage] = useState(''); return <ScrollView contentContainerStyle={[styles.content, styles.chatBackground]}><Text style={[styles.pageTitle, styles.chatHeading, rtl && styles.textRTL]}>{t.supportTitle}</Text><Text style={[styles.pageLead, styles.chatCopy, rtl && styles.textRTL]}>{t.supportText}</Text><View style={styles.supportCard}><Text style={styles.supportIcon}>◌</Text><Text style={styles.supportTitle}>{t.support}</Text><Text style={styles.supportCopy}>{t.featureDemo}</Text><TextInput value={message} onChangeText={setMessage} placeholder={t.messagePlaceholder} placeholderTextColor={INK} style={[styles.supportInput, rtl && styles.textRTL]} /><Button label={t.sendMessage} onPress={() => setMessage('')} /></View><FeatureTile icon="⌕" title={t.visualSearch} text={t.featureDemo} onPress={() => onFeature('visual')} /><FeatureTile icon="✦" title={t.tryOn} text={t.featureDemo} onPress={() => onFeature('tryon')} /><FeatureTile icon="▣" title={t.reels} text={t.featureDemo} onPress={() => onFeature('reels')} /><FeatureTile icon="◎" title={t.groupBuy} text={t.featureDemo} onPress={() => onFeature('group')} /></ScrollView>; }
function FeatureTile({ icon, title, text, onPress }: any) { return <Pressable onPress={onPress} style={styles.featureTile}><Text style={styles.featureTileIcon}>{icon}</Text><View style={{ flex: 1 }}><Text style={styles.roomTitle}>{title}</Text><Text style={styles.productStore}>{text}</Text></View><Text style={styles.arrow}>→</Text></Pressable>; }
function FeatureModal({ t, rtl, feature, onClose, onNotify }: any) { const title = feature === 'visual' ? t.visualSearch : feature === 'tryon' ? t.tryOn : feature === 'reels' ? t.reels : t.groupBuy; const icon = feature === 'visual' ? '⌕' : feature === 'tryon' ? '✦' : feature === 'reels' ? '▣' : '◎'; const openCamera = async () => { const permission = await ImagePicker.requestCameraPermissionsAsync(); if (!permission.granted) { onNotify('يلزم السماح بالكاميرا للبحث بالصورة'); return; } const result = await ImagePicker.launchCameraAsync({ mediaTypes: ImagePicker.MediaTypeOptions.Images, quality: 0.55 }); if (!result.canceled) onNotify('تم التقاط الصورة والبحث عن منتجات مماثلة'); }; const openGallery = async () => { const result = await ImagePicker.launchImageLibraryAsync({ mediaTypes: ImagePicker.MediaTypeOptions.Images, quality: 0.55 }); if (!result.canceled) onNotify('تم اختيار الصورة والبحث عن منتجات مماثلة'); }; return <View style={styles.modalSheet}><View style={styles.sheetHandle} /><Pressable onPress={onClose} style={styles.close}><Text>×</Text></Pressable><Text style={styles.featureModalIcon}>{icon}</Text><Text style={[styles.modalTitle, rtl && styles.textRTL]}>{title}</Text><Text style={[styles.modalText, rtl && styles.textRTL]}>{t.featureDemo}</Text>{feature === 'tryon' && <View style={styles.swatches}>{['#6B1724', '#FFC107', '#5B3425', '#C85632'].map(color => <Pressable key={color} onPress={() => onNotify(color)} style={[styles.swatch, { backgroundColor: color }]} />)}</View>}{feature === 'group' && <Text style={styles.modalText}>{t.groupBuy} · 2/3</Text>}{feature === 'visual' ? <><Button label="فتح الكاميرا" onPress={openCamera} /><Button label="اختيار صورة من المعرض" secondary onPress={openGallery} /></> : <Button label={t.sendRequest} onPress={() => onNotify(t.featureDemo)} />}<Button label={t.backShopping} secondary onPress={onClose} /></View>; }
function ProductModal({ t, rtl, product, onClose, onAdd }: any) { return <View style={styles.modalSheet}><View style={styles.sheetHandle} /><Pressable onPress={onClose} style={styles.close}><Text>×</Text></Pressable><View style={[styles.detailImage, product.large ? styles.machineImage : styles.groceryImage]}><Text style={{ fontSize: 70 }}>{product.large ? '⚙' : '✿'}</Text></View><Text style={[styles.detailTitle, rtl && styles.textRTL]}>{product.title}</Text><Text style={styles.productStore}>{product.store} · {product.governorate}</Text><Text style={styles.detailPrice}>{product.price} USD</Text><Text style={[styles.detailDescription, rtl && styles.textRTL]}>{t.heroText}</Text><Button label={t.add} onPress={onAdd} /></View>; }
function RoomModal({ t, rtl, room, onClose, onNotify }: any) { const admin = room === 'admin'; const large = room === 'large'; return <View style={styles.modalSheet}><View style={styles.sheetHandle} /><Pressable onPress={onClose} style={styles.close}><Text>×</Text></Pressable><Text style={styles.modalKicker}>{admin ? t.admin : large ? t.largeRoom : t.smallRoom}</Text><Text style={[styles.modalTitle, rtl && styles.textRTL]}>{admin ? t.adminReview : large ? t.largeDesc : t.smallDesc}</Text><View style={styles.roomStats}><Stat value={admin ? '7' : large ? '24' : '18'} label={t.product} /><Stat value={large ? '10 USD' : '1 USD'} label={t.promotion} /><Stat value="7" label={t.sevenDays} /></View><Text style={[styles.modalText, rtl && styles.textRTL]}>{t.manual}</Text><Button label={admin ? t.accept : t.sendRequest} onPress={() => onNotify(admin ? t.requestAccepted : t.requestSent)} /><Button label={admin ? t.reject : t.promotion} secondary onPress={() => onNotify(admin ? t.requestRejected : t.comingSoon)} /></View>; }
function Stat({ value, label }: any) { return <View style={styles.stat}><Text style={styles.statValue}>{value}</Text><Text style={styles.statLabel}>{label}</Text></View>; }
function Reels({ t, rtl, onFeature }: any) { const [duration, setDuration] = useState('20s'); const [filter, setFilter] = useState('Original'); const [liked, setLiked] = useState(false); const [comment, setComment] = useState(''); const [comments, setComments] = useState<string[]>([]); return <ScrollView contentContainerStyle={styles.content}><Text style={[styles.pageTitle, rtl && styles.textRTL]}>{t.reels}</Text><Text style={[styles.pageLead, rtl && styles.textRTL]}>{t.featureDemo}</Text><View style={styles.reelsPreview}><Text style={styles.reelsPlay}>▶</Text><Text style={styles.reelsWatermark}>{t.brand}</Text></View><View style={styles.reelActions}><Pressable onPress={() => setLiked(!liked)} style={[styles.reelAction, liked && styles.reelActionActive]}><Text style={styles.reelActionIcon}>{liked ? '♥' : '♡'}</Text><Text style={styles.reelActionText}>{liked ? '1' : '0'}</Text></Pressable><Pressable onPress={() => setComment('')} style={styles.reelAction}><Text style={styles.reelActionIcon}>◌</Text><Text style={styles.reelActionText}>{comments.length}</Text></Pressable><Pressable onPress={() => onFeature('reels')} style={styles.sellerButton}><Text style={styles.sellerButtonText}>@ {t.stores}</Text></Pressable></View><View style={styles.durationTabs}>{['10s', '20s', '60s'].map(item => <Pressable key={item} onPress={() => setDuration(item)} style={[styles.durationTab, duration === item && styles.durationTabActive]}><Text style={[styles.durationText, duration === item && styles.durationTextActive]}>{item === '60s' ? '1 min' : item}</Text></Pressable>)}</View><View style={styles.editorTools}><Pressable style={styles.editorTool} onPress={() => onFeature('reels')}><Text style={styles.editorIcon}>✂</Text><Text style={styles.roomTitle}>Edit</Text></Pressable><Pressable style={styles.editorTool} onPress={() => setFilter(filter === 'Original' ? 'Warm' : 'Original')}><Text style={styles.editorIcon}>◐</Text><Text style={styles.roomTitle}>Filter: {filter}</Text></Pressable><Pressable style={styles.editorTool} onPress={() => onFeature('tryon')}><Text style={styles.editorIcon}>♫</Text><Text style={styles.roomTitle}>Audio</Text></Pressable></View><View style={styles.commentBox}><TextInput value={comment} onChangeText={setComment} placeholder="اكتب تعليقك…" placeholderTextColor={INK} style={styles.commentInput} /><Pressable onPress={() => { if (comment.trim()) { setComments([...comments, comment.trim()]); setComment(''); } }} style={styles.commentSend}><Text style={styles.commentSendText}>➤</Text></Pressable></View>{comments.map((item, index) => <View key={`${item}-${index}`} style={styles.commentRow}><Text style={styles.commentAvatar}>●</Text><Text style={styles.commentText}>{item}</Text></View>)}<Button label={t.add} onPress={() => onFeature('reels')} /></ScrollView>; }
function MerchantDashboard({ t, rtl, onNotify, onBack }: any) { const [tab, setTab] = useState<'overview' | 'reels' | 'orders' | 'settings'>('overview'); const [reelTitle, setReelTitle] = useState(''); const [duration, setDuration] = useState('20s'); const [filter, setFilter] = useState('Original'); return <ScrollView contentContainerStyle={styles.content}><Pressable onPress={onBack} style={styles.backLink}><Text style={styles.backLinkText}>‹ {t.backShopping}</Text></Pressable><View style={styles.merchantHero}><View><Text style={styles.merchantEyebrow}>MERCHANT STUDIO · تجريبي</Text><Text style={styles.merchantTitle}>مونة الشام</Text><Text style={styles.merchantSub}>غرفة التاجر وإدارة حضور المتجر</Text></View><View style={styles.merchantAvatar}><Text>م</Text></View></View><View style={styles.merchantTabs}>{[['overview','نظرة عامة'],['reels','إنشاء Reels'],['orders','الطلبات'],['settings','إعدادات المتجر']].map(([key,label]) => <Pressable key={key} onPress={() => setTab(key as any)} style={[styles.merchantTab, tab === key && styles.merchantTabActive]}><Text style={[styles.merchantTabText, tab === key && styles.merchantTabTextActive]}>{label}</Text></Pressable>)}</View>{tab === 'overview' && <><Text style={styles.merchantSectionTitle}>مؤشرات المتجر</Text><View style={styles.metricGrid}><MetricCard icon='▣' value='—' label='الطلبات' note='تظهر بعد الربط الحقيقي' /><MetricCard icon='◉' value='—' label='الزيارات' note='تظهر من التحليلات' /><MetricCard icon='◌' value='—' label='التعليقات' note='بدون تقييمات وهمية' /><MetricCard icon='↗' value='—' label='مؤشر النمو' note='يحسب من بيانات فعلية' /></View><View style={styles.contractCard}><Text style={styles.contractTitle}>متطلبات تشغيل المتجر</Text><Text style={styles.contractText}>عقد شركة شحن ساري باسم التاجر: مطلوب قبل تفعيل التوصيل.</Text><Text style={styles.contractText}>قناة الإشعارات: WhatsApp فقط، دون SMS.</Text><Text style={styles.contractText}>مساعد الذكاء: Gemini جاهز للربط الآمن عبر الخادم.</Text><Button label='إضافة بيانات عقد الشحن' onPress={() => onNotify('سيتم حفظ بيانات العقد بعد ربط قاعدة البيانات')} /></View></>}{tab === 'reels' && <><Text style={styles.merchantSectionTitle}>إنشاء Reel للمتجر</Text><Text style={styles.merchantHint}>النشر متاح للتاجر فقط، ويمكن تحويل المقطع إلى إعلان بعد المراجعة.</Text><TextInput value={reelTitle} onChangeText={setReelTitle} placeholder='عنوان المقطع أو الإعلان' placeholderTextColor={MUTED} style={styles.merchantInput} /><View style={styles.reelCanvas}><Text style={styles.reelCanvasIcon}>＋</Text><Text style={styles.reelCanvasText}>أضف فيديو أو صورة للمنتج</Text><Text style={styles.merchantHint}>الكاميرا والمعرض متاحان في نسخة الهاتف</Text></View><View style={styles.durationTabs}>{['10s','20s','60s'].map(item => <Pressable key={item} onPress={() => setDuration(item)} style={[styles.durationTab, duration === item && styles.durationTabActive]}><Text style={[styles.durationText, duration === item && styles.durationTextActive]}>{item === '60s' ? '1 دقيقة' : item}</Text></Pressable>)}</View><View style={styles.editorTools}><Pressable style={styles.editorTool} onPress={() => onNotify('تم فتح أدوات القص والترتيب')}><Text style={styles.editorIcon}>✂</Text><Text style={styles.roomTitle}>قص وترتيب</Text></Pressable><Pressable style={styles.editorTool} onPress={() => setFilter(filter === 'Original' ? 'Warm' : 'Original')}><Text style={styles.editorIcon}>◐</Text><Text style={styles.roomTitle}>فلتر: {filter}</Text></Pressable><Pressable style={styles.editorTool} onPress={() => onNotify('تم فتح اختيار الصوت')}><Text style={styles.editorIcon}>♫</Text><Text style={styles.roomTitle}>صوت</Text></Pressable></View><Button label='نشر Reel' onPress={() => onNotify(reelTitle.trim() ? 'تم إرسال المقطع للمراجعة' : 'أضف عنوانًا قبل النشر')} /><Button label='تحويل إلى إعلان داخل Reels' secondary onPress={() => onNotify('يُرسل الإعلان إلى مراجعة المدير')} /></>}{tab === 'orders' && <><Text style={styles.merchantSectionTitle}>طلبات المتجر</Text><View style={styles.empty}><Text style={styles.emptyIcon}>▣</Text><Text style={styles.emptyTitle}>لا توجد بيانات طلبات متصلة بعد</Text><Text style={styles.pageLead}>ستظهر هنا حالات الدفع عند الباب والدفع اليدوي وEscrow بعد ربط الخادم.</Text></View></>}{tab === 'settings' && <><Text style={styles.merchantSectionTitle}>إعدادات المتجر</Text><SettingItem icon='▤' label='بيانات عقد الشحن' value='إلزامي قبل التفعيل' /><SettingItem icon='◌' label='قناة التواصل' value='WhatsApp فقط' /><SettingItem icon='✦' label='Gemini AI' value='جاهز للربط عبر الخادم' /><SettingItem icon='◎' label='صلاحية النشر' value='Reels والإعلانات للتاجر فقط' /></>}</ScrollView>; } function MetricCard({ icon, value, label, note }: any) { return <View style={styles.metricCard}><Text style={styles.metricIcon}>{icon}</Text><Text style={styles.metricValue}>{value}</Text><Text style={styles.metricLabel}>{label}</Text><Text style={styles.metricNote}>{note}</Text></View>; } function AdminPage({ t, rtl, onRoom }: any) { return <ScrollView contentContainerStyle={styles.content}><Text style={[styles.pageTitle, rtl && styles.textRTL]}>{t.admin}</Text><Text style={[styles.pageLead, rtl && styles.textRTL]}>{t.adminReview}</Text><View style={styles.adminHero}><Text style={styles.adminHeroIcon}>⌘</Text><Text style={styles.modalTitle}>{t.adminReview}</Text><Text style={styles.modalText}>{t.featureDemo}</Text></View><RoomLink t={t} icon="✓" title={t.promotion} text={t.requestAccepted} onPress={() => onRoom('admin')} /><RoomLink t={t} icon="▣" title={t.reels} text={t.featureDemo} onPress={() => onRoom('admin')} /><RoomLink t={t} icon="◌" title={t.cart} text={t.featureDemo} onPress={() => onRoom('admin')} /></ScrollView>; }
function BottomNav({ t, page, setPage, cartCount, rtl }: any) { const items = [{ key: 'home', label: t.home, icon: '⌂' }, { key: 'reels', label: t.reels, icon: '▶' }, { key: 'support', label: t.support, icon: '◌' }, { key: 'account', label: t.account, icon: '◉' }]; return <View style={[styles.bottomNav, rtl && styles.rowRTL]}>{items.slice(0, 2).map(item => <Pressable key={item.key} onPress={() => setPage(item.key)} style={[styles.navItem, page === item.key && styles.navActive]}><Text style={styles.navIcon}>{item.icon}</Text><Text style={[styles.navLabel, page === item.key && styles.navLabelActive]}>{item.label}</Text></Pressable>)}<Pressable onPress={() => setPage('cart')} style={styles.cartFab}><Text style={styles.cartFabIcon}>🛒</Text>{cartCount > 0 && <View style={styles.badge}><Text style={styles.badgeText}>{cartCount}</Text></View>}<Text style={styles.cartFabLabel}>{t.cart}</Text></Pressable>{items.slice(2).map(item => <Pressable key={item.key} onPress={() => setPage(item.key)} style={[styles.navItem, page === item.key && styles.navActive]}><Text style={styles.navIcon}>{item.icon}</Text><Text style={[styles.navLabel, page === item.key && styles.navLabelActive]}>{item.label}</Text></Pressable>)}</View>; }
function Button({ label, onPress, secondary }: { label: string; onPress: () => void; secondary?: boolean }) { return <Pressable onPress={onPress} style={[styles.button, secondary && styles.buttonSecondary]}><Text style={[styles.buttonText, secondary && styles.buttonSecondaryText]}>{label}</Text></Pressable>; }

